impl WolfModelVariant {
    pub fn for_resource_id(resource_id: &str) -> Option<Self> {
        VANILLA_WOLF_VARIANTS
            .iter()
            .find(|entry| entry.resource_id == resource_id)
            .map(|entry| entry.variant)
    }

    pub fn for_vanilla_registry_id(registry_id: i32) -> Option<Self> {
        VANILLA_WOLF_VARIANTS
            .get(usize::try_from(registry_id).ok()?)
            .map(|entry| entry.variant)
    }

    pub fn resource_id(self) -> &'static str {
        VANILLA_WOLF_VARIANTS[self as usize].resource_id
    }

    pub(in crate::entity_models) const fn builtin_texture_ref(
        self,
        baby: bool,
        tame: bool,
        angry: bool,
    ) -> EntityModelTextureRef {
        let age_offset = if baby { 3 } else { 0 };
        let state_offset = if tame {
            1
        } else if angry {
            2
        } else {
            0
        };
        VANILLA_WOLF_VARIANT_TEXTURE_REFS
            [VANILLA_WOLF_VARIANTS[self as usize].texture_start + age_offset + state_offset]
    }
}

#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn wolf_variant_catalog_is_complete_ordered_and_unique() {
        assert_eq!(VANILLA_WOLF_VARIANTS.len(), 9);
        let mut resources = HashSet::new();
        let mut textures = HashSet::new();
        for (registry_id, entry) in VANILLA_WOLF_VARIANTS.iter().enumerate() {
            assert_eq!(entry.variant as usize, registry_id);
            assert_eq!(entry.texture_start, registry_id * 6);
            assert!(resources.insert(entry.resource_id));
        }
        for texture in VANILLA_WOLF_VARIANT_TEXTURE_REFS {
            assert!(textures.insert(texture.path));
        }
    }

    #[test]
    fn wolf_variant_catalog_preserves_registry_and_resource_order() {
        assert_eq!(
            WolfModelVariant::for_vanilla_registry_id(0),
            Some(WolfModelVariant::Pale)
        );
        assert_eq!(
            WolfModelVariant::for_vanilla_registry_id(8),
            Some(WolfModelVariant::Striped)
        );
        assert_eq!(WolfModelVariant::for_vanilla_registry_id(-1), None);
        assert_eq!(WolfModelVariant::for_vanilla_registry_id(9), None);
        assert_eq!(
            WolfModelVariant::for_resource_id("minecraft:chestnut"),
            Some(WolfModelVariant::Chestnut)
        );
        assert_eq!(WolfModelVariant::for_resource_id("minecraft:blue"), None);
        assert_eq!(WolfModelVariant::Pale.resource_id(), "minecraft:pale");
        assert_eq!(
            WolfModelVariant::Pale
                .builtin_texture_ref(false, false, false)
                .path,
            "textures/entity/wolf/wolf.png"
        );
        assert_eq!(
            WolfModelVariant::Spotted
                .builtin_texture_ref(false, true, true)
                .path,
            "textures/entity/wolf/wolf_spotted_tame.png"
        );
        assert_eq!(
            WolfModelVariant::Striped
                .builtin_texture_ref(true, false, true)
                .path,
            "textures/entity/wolf/wolf_striped_angry_baby.png"
        );
        assert_eq!(
            WolfModelVariant::Striped
                .builtin_texture_ref(true, false, true)
                .size,
            [32, 32]
        );
    }

    #[test]
    fn production_sources_do_not_redeclare_wolf_variant_catalog_facts() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/wolf_variants.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                if source.contains("enum WolfModelVariant")
                    || source.contains("fn wolf_variant_from_entry_id(")
                    || source.contains("fn wolf_variant_from_vanilla_registry_id(")
                    || source.contains("fn vanilla_wolf_variant_resource_id(")
                    || source.contains("\"minecraft:pale\" => Some(WolfModelVariant::")
                    || source.contains("const WOLF_SPOTTED_TEXTURE_REF")
                    || source.contains("WolfModelVariant::Spotted => [")
                {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel wolf-variant catalog owners: {violations:?}"
        );
    }
}
